import React, { useId } from 'react'

export const LogoTransparent = ({className}: {className?: string}) => {
    const uniquePrefix = useId().replace(/:/g, "");
    const patternId = `${uniquePrefix}-pattern`;

    return (
        <svg className={className} width="181" height="40" viewBox="0 0 181 40" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
            <rect width="181" height="40" fill={`url(#${patternId})`} />
            <defs>
                <pattern id={patternId} patternContentUnits="objectBoundingBox" width="1" height="1">
                    <use xlinkHref="#image0_236_1057" transform="matrix(0.00128814 0 0 0.00589862 -0.129357 -2.11705)" />
                </pattern>
                <image id="image0_236_1057" width="960" height="960" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
            </defs>
        </svg>

    )
}
